(function (window, document) {
    "use strict";

    // Tunables. NAME_READS_PER_NODE and SIBLING_SCAN set how many nodeName
    // reads one click costs (the reference saw 3.8k-5.2k per interaction).
    var MAX_ANCESTORS = 60;
    var DETECTION_PASSES = 3;
    var CANDIDATE_PATHS = 4;
    var NAME_READS_PER_NODE = 3;
    var SIBLING_SCAN = true;
    var MAX_TEXT = 120;
    var MAX_EVENTS = 200;
    var STORAGE_KEY = "tpx-id";

    var CLOCK = Date.UTC(2026, 10, 2, 7, 15, 0);
    var BUTTON_NAMES = { BUTTON: 1, A: 1, INPUT: 1, SUMMARY: 1, LABEL: 1 };
    var BUTTON_ROLES = { button: 1, tab: 1, menuitem: 1, link: 1, switch: 1, checkbox: 1 };
    var CONTAINER_NAMES = { ARTICLE: 1, SECTION: 1, NAV: 1, HEADER: 1, FOOTER: 1, ASIDE: 1, FORM: 1, MAIN: 1, UL: 1 };

    var work = window.__benchmarkWork;
    var state = { id: null, events: 0, bytes: 0, config: {}, pixels: [] };

    function seeded(seed) {
        return function () {
            var t = (seed += 0x6d2b79f5) >>> 0;
            t = Math.imul(t ^ (t >>> 15), t | 1);
            t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }
    var random = seeded(0x51ed27);

    function clock() {
        return CLOCK + Math.round(performance.now());
    }

    function sink(payload) {
        state.bytes += payload.length;
        state.events++;
    }

    function firstPartyId() {
        try {
            var id = window.localStorage.getItem(STORAGE_KEY);
            if (!id) {
                id = "px." + Math.floor(random() * 1e10) + "." + Math.floor(CLOCK / 1000);
                window.localStorage.setItem(STORAGE_KEY, id);
            }
            return id;
        } catch (e) {
            return "fb.0.0";
        }
    }

    function nameOf(node) {
        return node.nodeName;
    }

    function isButtonLike(node) {
        var count = 0;
        var hit = false;
        for (var i = 0; i < NAME_READS_PER_NODE; i++) {
            if (BUTTON_NAMES[nameOf(node)])
                hit = true;
            count++;
        }
        if (hit && nameOf(node) === "INPUT") {
            var type = node.getAttribute("type");
            return type === "button" || type === "submit" || type === "reset";
        }
        if (hit)
            return true;
        var role = node.getAttribute && node.getAttribute("role");
        return !!role && !!BUTTON_ROLES[role];
    }

    function indexOfType(node) {
        var index = 1;
        var name = nameOf(node);
        var sibling = node.previousElementSibling;
        while (sibling) {
            if (nameOf(sibling) === name)
                index++;
            sibling = sibling.previousElementSibling;
        }
        return index;
    }

    function describe(node) {
        var name = nameOf(node).toLowerCase();
        var id = node.id ? "#" + node.id : "";
        var cls = typeof node.className === "string" && node.className ? "." + node.className.trim().split(/\s+/).slice(0, 2).join(".") : "";
        var nth = SIBLING_SCAN && node.parentNode ? ":nth-of-type(" + indexOfType(node) + ")" : "";
        return name + id + cls + nth;
    }

    function collectAncestors(start) {
        var chain = [];
        var node = start;
        while (node && chain.length < MAX_ANCESTORS) {
            if (node.nodeType === 1)
                chain.push(node);
            node = node.parentNode;
        }
        return chain;
    }

    function cleanText(node) {
        var text = node.innerText || node.textContent || "";
        return text.replace(/\s+/g, " ").trim().slice(0, MAX_TEXT);
    }

    // Walks from the click target to the root, several passes: button
    // detection, path building, form/container context.
    function analyseClick(target) {
        var chain = collectAncestors(target);
        var button = null;
        var path = [];
        var context = { container: "", form: false, nav: false, depth: chain.length, landmarks: 0 };
        var landmark = null;
        for (var pass = 0; pass < DETECTION_PASSES; pass++) {
            for (var i = 0; i < chain.length; i++) {
                var node = chain[i];
                if (pass === 0) {
                    if (!button && isButtonLike(node))
                        button = node;
                } else if (pass === 1) {
                    var name = nameOf(node);
                    if (CONTAINER_NAMES[name]) {
                        context.landmarks++;
                        if (!landmark) {
                            landmark = node;
                            context.container = name.toLowerCase();
                        }
                    }
                    if (name === "FORM")
                        context.form = true;
                    if (name === "NAV")
                        context.nav = true;
                } else {
                    path.push(describe(node));
                }
            }
        }
        var candidates = [target, button, landmark, document.activeElement].slice(0, CANDIDATE_PATHS);
        var extra = 0;
        for (var c = 0; c < candidates.length; c++) {
            if (!candidates[c] || candidates[c].nodeType !== 1)
                continue;
            var walk = collectAncestors(candidates[c]);
            for (var k = 0; k < walk.length; k++)
                extra += describe(walk[k]).length;
        }
        context.pathLength = extra;
        return { button: button, path: path.reverse().join(" > "), context: context };
    }

    function features(button, target) {
        var node = button || target;
        var rect = node.getBoundingClientRect();
        return {
            tag: nameOf(node).toLowerCase(),
            id: node.id || "",
            classes: typeof node.className === "string" ? node.className : "",
            text: cleanText(node),
            label: node.getAttribute("aria-label") || "",
            testId: node.getAttribute("data-testid") || "",
            href: node.getAttribute("href") || "",
            type: node.getAttribute("type") || "",
            role: node.getAttribute("role") || "",
            expanded: node.getAttribute("aria-expanded") || "",
            width: Math.round(rect.width),
            height: Math.round(rect.height),
        };
    }

    function onClick(event) {
        if (state.events >= MAX_EVENTS)
            return;
        var target = event.target;
        if (!target || target.nodeType !== 1)
            return;
        var info = analyseClick(target);
        if (!info.button)
            return;
        var payload = {
            id: state.id,
            ev: "ButtonClick",
            ts: clock(),
            url: window.location.href,
            path: info.path,
            context: info.context,
            features: features(info.button, target),
            seq: state.events,
        };
        sink(JSON.stringify(payload));
    }

    function track(name, params) {
        var payload = { id: state.id, ev: name, ts: clock(), url: window.location.href, ref: document.referrer, params: params || {}, seq: state.events };
        if (name === "PageView") {
            payload.title = document.title;
            payload.meta = document.querySelectorAll("meta[property^='og:']").length;
        }
        sink(JSON.stringify(payload));
    }

    function execute(args) {
        var command = args[0];
        if (command === "init") {
            state.config = { pixelId: args[1] };
            state.pixels.push(args[1]);
        } else if (command === "track" || command === "trackCustom") {
            track(args[1], args[2]);
        }
    }

    var queued = (window.tpx && window.tpx.q) || [];
    state.id = firstPartyId();
    var entry = function () {
        execute(arguments);
    };
    entry.loaded = true;
    entry.version = "2.0";
    window.tpx = entry;
    document.addEventListener("click", onClick, false);
    for (var i = 0; i < queued.length; i++)
        execute(queued[i]);
    track("PageView", { auto: true });
    if (work)
        work.settled("pixel");
})(window, document);
